def apng(name,ims):
 def chunk(k,d):return struct.pack('>I',len(d))+k+d+struct.pack('>I',zlib.crc32(k+d)&0xffffffff)
 w,h=ims[0].size;p=b'\x89PNG\r\n\x1a\n'+chunk(b'IHDR',struct.pack('>IIBBBBB',w,h,8,6,0,0,0))+chunk(b'acTL',struct.pack('>II',3,0));num=0
 for k,(im,t) in enumerate(zip([ims[0],ims[1],ims[0]],[60,3,27])):
  p+=chunk(b'fcTL',struct.pack('>IIIIIHHBB',num,w,h,0,0,t,30,0,0));num+=1;a=np.array(im);data=zlib.compress(b''.join(b'\0'+a[y].tobytes() for y in range(h)),9)
  if k==0:p+=chunk(b'IDAT',data)
  else:p+=chunk(b'fdAT',struct.pack('>I',num)+data);num+=1
 (P/name).write_bytes(p+chunk(b'IEND',b''))
apng('idle-blink.apng',images);world=[im.resize((200,200),Image.Resampling.NEAREST) for im in images];apng('yard-scale-blink.apng',world);gif=[]
for im in [world[0],world[1],world[0]]:
 bg=Image.new('RGBA',im.size,'#d9d4bd');bg.alpha_composite(im);gif.append(bg.convert('RGB'))
gif[0].save(P/'California-Scrub-Jay-Blink-Yard-Scale.gif',save_all=True,append_images=gif[1:],duration=[2000,100,900],loop=0,optimize=False)
