 for i,(im,rect,label) in enumerate(zip([old,new],rects,['EXISTING AWAKE','ONE NEW CLOSED'])):
  draw.text((i*size[0]+8,8),label,fill='#24342b');sheet.alpha_composite(im.crop(rect).resize(size,Image.Resampling.NEAREST),(i*size[0],30))
 sheet.convert('RGB').save(P/(kind+'-review-crops.png'))
