primary={'batchId':'sd20-california-scrub-jay-blink-v1','nativeCalls':1,'original':'original.png','originalSHA256':sha((P/'original.png').read_bytes()),'prompt':'prompt.txt','promptSHA256':sha((P/'prompt.txt').read_bytes()),'frames':[{'sourceFrameId':fid(new),'sourcePNG':'closed-native.png','sourcePNGsha256':sha((P/'closed-native.png').read_bytes()),'speciesId':'california_scrub_jay','pose':'closed-eye blink','registration':{'nativeCanvas':[1254,1254],'pixelRegistration':'none; native source PNG retained byte-identical','wholeCallCanvasDensityConversion':{'requestedCanvas':[1024,1024],'actualNativeCanvas':[1254,1254],'nativeToReferenceCanvasRatio':1024/1254,'nativeToOutputRatio':192/1254},'perPoseFit':False,'paintOrWarp':False,'alphaErasure':False},'outputPNG':'closed192.png','outputPNGsha256':sha((P/'closed192.png').read_bytes())}],'reusedFrames':[{'sourceFrameId':fid(old),'sourcePNG':'reused-awake-source1024.png','sourcePNGsha256':sha((P/'reused-awake-source1024.png').read_bytes()),'speciesId':'california_scrub_jay','pose':'existing awake neutral unchanged','outputPNG':'reused-awake192.png','outputPNGsha256':sha((P/'reused-awake192.png').read_bytes()),'newDrawing':False}],'outputMetadata':['texture-review-manifest.json','static-review-manifest.json','scale-contact-measurements.json','behavior-handoff.json','verification.json','browser-verification.json','independent-review.json'],'sourceStatus':'stable-source-awaiting-independent-compatibility-review','notes':['Exactly ONE new closed-eye drawing; existing awake reused unchanged. No new neutral, crop, rescale or trajectory counted as another drawing.','Canvas conversion is whole-native-call density normalization1254 to reference1024 coordinates/output192, never perpose silhouette fitting.','If normal-size identity/contact compatibility fails, retain closure as study; no automatic retry.']};J('PRIMARY-SOURCE-MANIFEST.json',primary)
bboxes=[];feet=[];density=f['sourcePixelsPerWorldUnit'];y,x=np.indices((192,192))
for a in arrays:
 yy,xx=np.where(a[:,:,3]>=128);bboxes.append([int(xx.min()),int(yy.min()),int(xx.max()+1),int(yy.max()+1)]);parts=[]
 for side in [x<116,x>=116]:
  yy,xx=np.where((a[:,:,3]>=128)&side&(x>=98)&(x<=132)&(y>=140)&(y<=151));parts.append({'bbox':[int(xx.min()),int(yy.min()),int(xx.max()+1),int(yy.max()+1)],'lowestRow':int(yy.max()),'centroid':[float(xx.mean()),float(yy.mean())]})
 feet.append(parts)
