measure={'sourceCanvases':{'unchangedReusedAwake':[1024,1024],'oneNewClosed':[1254,1254]},'outputCanvas':[192,192],'wholeCallNativeDensityConversion':1024/1254,'resampling':'Each entire native canvas nearest to192. Awake192 PNG reused byte-identical. No perpose fit, crop/warp/painting/alpha erasure.','existingIntakeDensityPreserved':density,'existingWorldCanvasPreserved':f['world'],'rootOutput':[114,150],'contactsUnchangedFromExistingIntake':f['contacts'],'visibleAlpha128BBoxes':bboxes,'visibleWidthsWorld':[(b[2]-b[0])/density for b in bboxes],'visibleHeightsWorld':[(b[3]-b[1])/density for b in bboxes],'footHeuristics':feet,'maximumFootCentroidChangeOutputPx':centroid,'maximumFootCentroidChangeWorld':centroid/density,'maximumFootBaselineRowChangeOutputPx':max(abs(a['lowestRow']-b['lowestRow']) for a,b in zip(feet[0],feet[1])),'fullAlpha128IoU':float((alpha[0]&alpha[1]).sum()/(alpha[0]|alpha[1]).sum()),'changedOutputRGBAPixels':int(np.any(arrays[0]!=arrays[1],axis=2).sum()),'loopEndpointChangedRGBA':0,'sourceEyeCrop':{'awake':list(eyeOld),'closedNative':list(eyeNew)},'sourceContactCrop':{'awake':list(feetOld),'closedNative':list(feetNew)},'notes':['Alpha/contact and changed-pixel counts are diagnostics, not semantic blink acceptance.','Shared positive-alpha contact pixels retain technical contract, not a physical support certification.','Nearest export samples alpha; all original/native-source RGBA bytes remain retained unchanged.']};J('scale-contact-measurements.json',measure)
